compare.check:
(args, got, expected) => {
    if (typeof got !== "string" || got.length !== expected.length) return false;
    const cnt = { a: 0, b: 0, c: 0 };
    for (let i = 0; i < got.length; i++) {
      const ch = got[i];
      if (!(ch in cnt)) return false;
      cnt[ch]++;
      if (i >= 2 && got[i - 1] === ch && got[i - 2] === ch) return false;
    }
    return cnt.a <= args[0] && cnt.b <= args[1] && cnt.c <= args[2];
  }
